//! System-wide manifests for the installers (ADR-0083): generated by
//! `mosaic-native-host manifest --system` from the same [`manifest_json`] as
//! the developer install, so the two cannot drift.

use super::{Error, ManifestFile, Os, Path, PathBuf, fs, manifest_json, windows_manifest_name};
use crate::ids::HOST_NAME;

/// Where the Linux packages install the host.
pub const LINUX_SYSTEM_HOST: &str = "/usr/lib/mosaic/mosaic-native-host";

/// Where the per-machine MSI installs the host.
pub const WINDOWS_SYSTEM_HOST: &str = r"C:\Program Files\Mosaic\mosaic-native-host.exe";

/// The host path of the packages for `os`; `None` where there are no system
/// manifests (macOS repairs per-user manifests instead).
#[must_use]
pub const fn system_host(os: Os) -> Option<&'static str> {
    match os {
        Os::Linux => Some(LINUX_SYSTEM_HOST),
        Os::Windows => Some(WINDOWS_SYSTEM_HOST),
        Os::MacOs => None,
    }
}

/// Whether `host` is an absolute path in the conventions of `os` (checked on
/// the text, so a build machine can generate manifests for another OS).
fn absolute_for(os: Os, host: &str) -> bool {
    match os {
        Os::Windows => {
            let mut chars = host.chars();
            let drive = matches!(
                (chars.next(), chars.next(), chars.next(), chars.next()),
                (Some(d), Some(':'), Some('\\'), Some(_)) if d.is_ascii_alphabetic()
            );
            drive || host.starts_with(r"\\")
        }
        _ => host.starts_with('/'),
    }
}

/// The system manifests for `os` with the host at `host`, as files below an
/// output root. Linux paths mirror the filesystem (`etc/opt/chrome/...`);
/// Windows gets the two files the MSI installs in `native-messaging\`.
///
/// # Errors
/// [`Error::Install`] for macOS or a `host` that is not absolute for `os`.
pub fn system_plan(os: Os, host: &str) -> Result<Vec<ManifestFile>, Error> {
    if !absolute_for(os, host) {
        return Err(Error::Install);
    }
    let host = Path::new(host);
    let name = format!("{HOST_NAME}.json");
    let file = |path: PathBuf, firefox: bool| ManifestFile {
        path,
        contents: manifest_json(firefox, host),
    };
    match os {
        Os::MacOs => Err(Error::Install),
        Os::Windows => Ok(vec![
            file(PathBuf::from(windows_manifest_name(false)), false),
            file(PathBuf::from(windows_manifest_name(true)), true),
        ]),
        Os::Linux => Ok([
            ("etc/opt/chrome/native-messaging-hosts", false),
            ("etc/opt/edge/native-messaging-hosts", false),
            ("etc/chromium/native-messaging-hosts", false),
            ("usr/lib/mozilla/native-messaging-hosts", true),
        ]
        .into_iter()
        .map(|(dir, firefox)| file(PathBuf::from(dir).join(&name), firefox))
        .collect()),
    }
}

/// Writes [`system_plan`] below `out`; returns the files written.
///
/// # Errors
/// [`Error::Install`] as for [`system_plan`], or if a file could not be
/// written.
pub fn write_system(os: Os, host: &str, out: &Path) -> Result<Vec<PathBuf>, Error> {
    let mut written = Vec::new();
    for file in system_plan(os, host)? {
        let path = out.join(&file.path);
        let dir = path.parent().ok_or(Error::Install)?;
        fs::create_dir_all(dir).map_err(|_| Error::Install)?;
        fs::write(&path, &file.contents).map_err(|_| Error::Install)?;
        written.push(path);
    }
    Ok(written)
}
